impl TryFrom<raw::BareKey> for validated::BareKey {
    type Error = ValidationError;
    fn try_from(value: raw::BareKey) -> Result<Self, Self::Error> {
        match value {
            raw::BareKey::PageDown => Ok(Self::PageDown),
            raw::BareKey::PageUp => Ok(Self::PageUp),
            raw::BareKey::Left => Ok(Self::Left),
            raw::BareKey::Down => Ok(Self::Down),
            raw::BareKey::Up => Ok(Self::Up),
            raw::BareKey::Right => Ok(Self::Right),
            raw::BareKey::Home => Ok(Self::Home),
            raw::BareKey::End => Ok(Self::End),
            raw::BareKey::Backspace => Ok(Self::Backspace),
            raw::BareKey::Delete => Ok(Self::Delete),
            raw::BareKey::Insert => Ok(Self::Insert),
            raw::BareKey::F(field_0) => Ok(Self::F(
                field_0,
            )),
            raw::BareKey::Char(field_0) => Ok(Self::Char(
                field_0,
            )),
            raw::BareKey::Tab => Ok(Self::Tab),
            raw::BareKey::Esc => Ok(Self::Esc),
            raw::BareKey::Enter => Ok(Self::Enter),
            raw::BareKey::CapsLock => Ok(Self::CapsLock),
            raw::BareKey::ScrollLock => Ok(Self::ScrollLock),
            raw::BareKey::NumLock => Ok(Self::NumLock),
            raw::BareKey::PrintScreen => Ok(Self::PrintScreen),
            raw::BareKey::Pause => Ok(Self::Pause),
            raw::BareKey::Menu => Ok(Self::Menu),
        }
    }
}

